-- 0180: aṣl from every book, batch 02 — each book's own statement (read by its profile; Lane in English), verbatim with
-- block + page and a plain English line; primary = the meaning most books share. Quotes checked against their blocks.
-- aslmb_02: aṣl per book for 25 roots that rested on Ibn Fāris alone (AGR:VOC:002/017).
-- Each row: the book's own words as printed + block + page + entry. ONE primary per root, by the reading most books share
-- (tie -> the earliest book). Standalone: INSERT OR IGNORE + guarded UPDATEs; safe to re-run. No row deleted.
-- امم
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:امم:jawhari_sihah', 'امم', '3b7af91ea46f2f492337f4eaa6', 'أُمُّ الشي: أصلُهُ', 'a thing''s ''mother'' is where it comes from', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_e7f9ec2676c4f2da', '3691', 5, 'blk_sih_7aff6174944b62e2', 0, NULL, 'Marker: head gloss. Reading: source. Differs from the main reading (heading for).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:امم:raghib_mufradat', 'امم', '3b7af91ea46f2f492337f4eaa6', 'ويقال لكل ما كان أصلا لوجود شيء أو تربيته أو إصلاحه أو مبدئه أمّ', 'what a thing comes from or grows by: its ''umm''', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_f16edef9e3bac0f4', '85', 1, 'blk_mfr_773c89e17d90b6cf', 0, NULL, 'Marker: «أصلا … أمّ». Reading: source. Differs from the main reading (heading for).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:امم:ibn_manzur_lisan_arab', 'امم', '3b7af91ea46f2f492337f4eaa6', 'الأَمُّ، بِالْفَتْحِ: القَصْد', 'amm: heading for something', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_3bb19cfd1e69ffb6', '5938', 12, 'blk_lsn_05ed53449774b40b', 0, NULL, 'Marker: head gloss. Reading: heading for. Primary: heading for — 4 of 7 books (Lisān blk_lsn_05ed53449774b40b; al-Miṣbāḥ blk_msb_08ef2e232deb8422; Tāj blk_taj_2bb4a2ac8b8f9800; Lane blk_lane_2ad83b512bb4331b). Other readings: source: al-Jawharī, Ibn Fāris, al-Rāghib · place to turn to: Ibn Fāris · group: Ibn Fāris · religion: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:امم:fayyumi_misbah_munir', 'امم', '3b7af91ea46f2f492337f4eaa6', 'أَمَّهُ أَمًّا مِنْ بَابِ قَتَلَ قَصْدَهُ', 'he headed for him', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_6336dac219eb1d17', '118', NULL, 'blk_msb_08ef2e232deb8422', 0, NULL, 'Marker: head gloss. Reading: heading for.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:امم:zabidi_taj_arus', 'امم', '3b7af91ea46f2f492337f4eaa6', 'أَمًّا: (قَصَده) وتوجَّه إِلَيْه', 'he headed for him and turned toward him', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_466d019cc127f9bd', '227', 31, 'blk_taj_2bb4a2ac8b8f9800', 0, NULL, 'Marker: Qāmūs gloss + addition. Reading: heading for.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:امم:lane_lexicon', 'امم', '3b7af91ea46f2f492337f4eaa6', 'He tended, repaired, betook himself, or directed his course, to, or towards, him, or it', 'he headed toward him or it', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_acb327bfc994f115', '86', NULL, 'blk_lane_2ad83b512bb4331b', 0, NULL, 'Marker: first sense A1. Reading: heading for.', 'high', 'active');
