INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:اني:ibn_durayd_jamharat_lugha', 'اني', 'b0ac1d63c7e330fed1a79bdeff', 'وآناء اللَّيْل: وَاحِدهَا إِنِّي وَهِي السَّاعَة من اللَّيْل', 'night hours; one is an hour of the night', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_2e809ed13482c276', '189', NULL, 'blk_jam_8ce5e3d038339a30', 0, NULL, 'Marker: head gloss. Reading: hour of time. Differs from the main reading (coming due).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:اني:jawhari_sihah', 'اني', 'b0ac1d63c7e330fed1a79bdeff', 'أنى الشئ يأنى إنى، أي حانَ. وأَنى أيضاً: أدرك', 'its time came; also: it ripened', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_0124e8544c609f3f', '4505', 6, 'blk_sih_07cb496aaf3d30be', 0, NULL, 'Marker: head gloss. Reading: time coming. Primary: coming due — 5 of 7 books (al-Jawharī blk_sih_07cb496aaf3d30be; Ibn Fāris blk_mqy_450263427296a614; Lisān blk_lsn_4f028f9a4fdc91fc; al-Qāmūs blk_qms_3542c24e233467f9; Lane blk_lane_9e373f0422ccd743). Other readings: hour of time: Ibn Durayd, Ibn Fāris, al-Miṣbāḥ · slowness: Ibn Fāris · vessel: Ibn Fāris.', 'high', 'active');
