INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:اني:fayyumi_misbah_munir', 'اني', 'b0ac1d63c7e330fed1a79bdeff', 'الْآنَاءُ عَلَى أَفْعَالٍ هِيَ الْأَوْقَاتُ', 'ānāʾ means times', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_dcff517b915c4059', '131', NULL, 'blk_msb_bee2308665c6577e', 0, NULL, 'Marker: head gloss. Reading: times. Differs from the main reading (coming due).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:اني:qamus_muhit', 'اني', 'b0ac1d63c7e330fed1a79bdeff', 'أنَى الشيءُ انْياً وأناءً وإنًى، بالكسر، وهو أنِيٌّ، كَغَنِيٍّ: حانَ، وأدْرَكَ، أو خاصٌّ بالنَّباتِ', 'its time came and it ripened; or only of plants', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_2de24fe0d3361d5c', NULL, NULL, 'blk_qms_3542c24e233467f9', 0, NULL, 'Marker: Qāmūs gloss. Reading: time coming.', 'high', 'active');
