INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:بخع:zabidi_taj_arus', 'بخع', '7253f41cd4b426bdf7de1c199e', 'بَخَعَ نَفْسَهُ، كمَنَعَ: قَتَلَها غَمَّاً، نَقَلَهُ الجَوْهَرِيّ، وَهُوَ مَجَازٌ', 'he killed himself with grief; a figure of speech', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_3efd7352c0704745', '305', 20, 'blk_taj_ced23b15a6d60dee', 0, NULL, 'Marker: Qāmūs gloss. Reading: killing oneself.', 'high', 'active');
